#include <array>
#include <string_view>

double weekAverage(const std::array<double, 7>& temps)
{
    double total{ 0.0 };
    for (double t : temps)
    {
        total += t;
    }
    return total / static_cast<double>(temps.size());
}

std::string_view hottestDay(const std::array<double, 7>& temps)
{
    constexpr std::array<std::string_view, 7> names{ "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday" };
    std::size_t best{ 0 };
    for (std::size_t i{ 1 }; i < temps.size(); ++i)
    {
        if (temps[i] > temps[best])
        {
            best = i;
        }
    }
    return names[best];
}

int daysAbove(const std::array<double, 7>& temps, double limit)
{
    int count{ 0 };
    for (double t : temps)
    {
        if (t > limit)
        {
            ++count;
        }
    }
    return count;
}

unitTests:
constexpr std::array<double, 7> week{ 14.0, 17.5, 21.0, 19.5, 21.0, 12.0, 9.0 };
TEST("weekAverage") { CHECK_NEAR(weekAverage(week), 16.285714, 1e-5); }
TEST("hottestDay, earliest wins a tie") { CHECK_EQ(hottestDay(week), "Wednesday"); }
TEST("hottestDay at the ends") { CHECK_EQ(hottestDay({ 30, 1, 1, 1, 1, 1, 1 }), "Monday"); CHECK_EQ(hottestDay({ 1, 1, 1, 1, 1, 1, 30 }), "Sunday"); }
TEST("daysAbove") { CHECK_EQ(daysAbove(week, 15.0), 4); CHECK_EQ(daysAbove(week, 21.0), 0); CHECK_EQ(daysAbove(week, 0.0), 7); }

